import gurobipy as gp
from gurobipy import GRB
import json

slots = [
    {
        "slot_id": 1,
        "quantity": 1,
        "candidates": [
            {"product_id": "09a33a1a", "price": 149.9},
            {"product_id": "0f90becb", "price": 189.9},
            {"product_id": "62018291", "price": 329.0},
            {"product_id": "ed8723f1", "price": 449.9},
        ],
    },
    {
        "slot_id": 2,
        "quantity": 1,
        "candidates": [
            {"product_id": "10d7d36d", "price": 649.9},
        ],
    },
    {
        "slot_id": 3,
        "quantity": 1,
        "candidates": [
            {"product_id": "1a4f7efe", "price": 899.0},
        ],
    },
    {
        "slot_id": 4,
        "quantity": 1,
        "candidates": [
            {"product_id": "812d64c7", "price": 849.9},
        ],
    },
]

env = gp.Env(empty=True)
env.setParam("OutputFlag", 0)
env.start()
model = gp.Model("shopping", env=env)

x = {}
for slot in slots:
    for cand in slot["candidates"]:
        x[(slot["slot_id"], cand["product_id"])] = model.addVar(
            vtype=GRB.BINARY, name=f"x_{slot['slot_id']}_{cand['product_id']}"
        )

for slot in slots:
    model.addConstr(
        gp.quicksum(x[(slot["slot_id"], c["product_id"])] for c in slot["candidates"]) == 1
    )

model.setObjective(
    gp.quicksum(
        slot["quantity"] * cand["price"] * x[(slot["slot_id"], cand["product_id"])]
        for slot in slots
        for cand in slot["candidates"]
    ),
    GRB.MINIMIZE,
)

model.optimize()

if model.status == GRB.OPTIMAL:
    selected = []
    total = 0.0
    for slot in slots:
        for cand in slot["candidates"]:
            if x[(slot["slot_id"], cand["product_id"])].X > 0.5:
                selected.append(
                    {
                        "slot_id": slot["slot_id"],
                        "product_id": cand["product_id"],
                        "quantity": slot["quantity"],
                        "unit_price": cand["price"],
                    }
                )
                total += slot["quantity"] * cand["price"]
    print(json.dumps({"status": "optimal", "selected_products": selected, "total_price": total}))
else:
    print(json.dumps({"status": "infeasible", "selected_products": [], "total_price": None}))
